#include <algorithm>
#include <charconv>
#include <fstream>
#include <set>
#include <sstream>
#include <stdexcept>

namespace genomic::gpi {
namespace {
std::string hex(const std::string& value){static constexpr char digits[]="0123456789abcdef";std::string result;for(const unsigned char c:value){result+=digits[c>>4];result+=digits[c&15];}return result;}
std::string unhex(const std::string& value){if(value.size()%2)throw std::runtime_error("Corrupt GDIS1 field");auto digit=[](char c)->unsigned{if(c>='0'&&c<='9')return static_cast<unsigned>(c-'0');if(c>='a'&&c<='f')return static_cast<unsigned>(c-'a'+10);throw std::runtime_error("Corrupt GDIS1 hex");};std::string result;for(std::size_t i=0;i<value.size();i+=2)result+=static_cast<char>((digit(value[i])<<4)|digit(value[i+1]));return result;}
std::vector<std::string> split(const std::string& value,char delimiter){std::vector<std::string> result;std::size_t begin=0;while(begin<=value.size()){const auto end=value.find(delimiter,begin);result.push_back(value.substr(begin,end==std::string::npos?end:end-begin));if(end==std::string::npos)break;begin=end+1;}return result;}
std::string join(const std::vector<std::string>& values,char delimiter){std::string result;for(const auto& value:values){if(!result.empty())result+=delimiter;result+=value;}return result;}
std::uint64_t stableHash(std::string_view value){std::uint64_t hash=1469598103934665603ULL;for(const unsigned char c:value){hash^=c;hash*=1099511628211ULL;}return hash;}
std::uint64_t number(const std::string& value){std::uint64_t result{};const auto [end,error]=std::from_chars(value.data(),value.data()+value.size(),result);if(error!=std::errc{}||end!=value.data()+value.size())throw std::runtime_error("Corrupt GDIS1 integer");return result;}
std::string diagnosticName(BuildDiagnosticClass value){return std::to_string(static_cast<int>(value));}
bool compatible(const DevelopmentStrategy& strategy,const BuildContract& contract){return (strategy.requiredBuildSystem.empty()||strategy.requiredBuildSystem==toString(contract.buildSystem))&&(strategy.requiredCompilerFamily.empty()||contract.compilerFamily.value.empty()||strategy.requiredCompilerFamily==contract.compilerFamily.value);}
StrategyOperator makeOperator(std::string id,std::string operation,std::vector<std::string> prerequisites,std::vector<std::string> dependencies,std::vector<std::string> effects,std::vector<std::string> verification,bool mutates=false){return {std::move(id),std::move(operation),std::move(prerequisites),std::move(dependencies),std::move(effects),std::move(verification),mutates};}
bool acyclic(const DevelopmentStrategy& strategy){std::set<std::string> complete;for(const auto& operation:strategy.operators){if(operation.id.empty()||complete.contains(operation.id))return false;if(!std::all_of(operation.dependsOn.begin(),operation.dependsOn.end(),[&](const auto& dependency){return complete.contains(dependency);} ))return false;complete.insert(operation.id);}return true;}
std::string serializeStrategy(const DevelopmentStrategy& strategy){std::ostringstream output;output<<"STRATEGY|"<<hex(strategy.id)<<'|'<<hex(strategy.version)<<'|'<<hex(strategy.goal)<<'|'<<hex(strategy.origin)<<'|'<<hex(strategy.requiredBuildSystem)<<'|'<<hex(strategy.requiredCompilerFamily)<<'|'<<strategy.confidence<<'|'<<static_cast<int>(strategy.status)<<'\n';
    const std::vector<std::pair<std::string,const std::vector<std::string>*>> lists={{"triggers",&strategy.triggers},{"prerequisites",&strategy.prerequisites},{"targetState",&strategy.targetState},{"verificationConditions",&strategy.verificationConditions},{"rollbackInformation",&strategy.rollbackInformation},{"safetyRequirements",&strategy.safetyRequirements},{"successfulContexts",&strategy.successfulContexts},{"failedContexts",&strategy.failedContexts}};for(const auto& [name,values]:lists)for(const auto& value:*values)output<<"LIST|"<<name<<'|'<<hex(value)<<'\n';
    for(const auto& operation:strategy.operators)output<<"OP|"<<hex(operation.id)<<'|'<<hex(operation.operation)<<'|'<<hex(join(operation.prerequisites,'\t'))<<'|'<<hex(join(operation.dependsOn,'\t'))<<'|'<<hex(join(operation.expectedEffects,'\t'))<<'|'<<hex(join(operation.verification,'\t'))<<'|'<<(operation.mutatesSources?1:0)<<'\n';
    return output.str();
}
void appendList(DevelopmentStrategy& strategy,const std::string& name,std::string value){if(name=="triggers")strategy.triggers.push_back(std::move(value));else if(name=="prerequisites")strategy.prerequisites.push_back(std::move(value));else if(name=="targetState")strategy.targetState.push_back(std::move(value));else if(name=="verificationConditions")strategy.verificationConditions.push_back(std::move(value));else if(name=="rollbackInformation")strategy.rollbackInformation.push_back(std::move(value));else if(name=="safetyRequirements")strategy.safetyRequirements.push_back(std::move(value));else if(name=="successfulContexts")strategy.successfulContexts.push_back(std::move(value));else if(name=="failedContexts")strategy.failedContexts.push_back(std::move(value));else throw std::runtime_error("Unknown GDIS1 list");}
std::vector<std::string> decodedList(const std::string& encoded){auto values=split(unhex(encoded),'\t');if(values.size()==1&&values.front().empty())values.clear();return values;}
}

double strategyTransferScore(const DevelopmentStrategy& strategy,const BuildContract& contract,const std::vector<BuildDiagnostic>& diagnostics){if(!compatible(strategy,contract)||!acyclic(strategy))return -1.0;double score=strategy.confidence;if(strategy.requiredBuildSystem==toString(contract.buildSystem))score+=0.25;if(!strategy.requiredCompilerFamily.empty()&&strategy.requiredCompilerFamily==contract.compilerFamily.value)score+=0.2;for(const auto& trigger:strategy.triggers)for(const auto& diagnostic:diagnostics)if(trigger==diagnosticName(diagnostic.classification))score+=0.1;for(const auto& failed:strategy.failedContexts)if(failed==toString(contract.buildSystem))score-=0.3;return std::clamp(score,0.0,1.0);}

std::vector<DevelopmentStrategy> DevelopmentStrategyInductionEngine::induce(const StrategyPlanningRequest& request) const {
    std::vector<DevelopmentStrategy> result;if(request.searchBudget==0||request.contract.buildSystem==BuildSystemKind::Unknown)return result;
    DevelopmentStrategy baseline;baseline.id="induced:native-baseline:"+std::string(toString(request.contract.buildSystem));baseline.goal=request.goal;baseline.origin="R15 build contract and causal diagnostics";baseline.requiredBuildSystem=toString(request.contract.buildSystem);baseline.requiredCompilerFamily=request.contract.compilerFamily.value;baseline.triggers={"build_contract_available"};baseline.prerequisites={"isolated_workspace","immutable_original","native_toolchain_available"};baseline.targetState={"baseline_classified","native_artifacts_recorded"};baseline.verificationConditions={"native_exit_codes","original_manifest_unchanged"};baseline.rollbackInformation={"discard isolated workspace"};baseline.safetyRequirements={"no original writeback","bounded process execution"};baseline.operators.push_back(makeOperator("discover","DISCOVER_BUILD_CONTRACT",{}, {},{"contract_discovered"},{"contract_has_origin"}));baseline.operators.push_back(makeOperator("baseline","RECONSTRUCT_BASELINE",{"contract_discovered"},{"discover"},{"baseline_classified"},{"native_build_result"}));baseline.operators.push_back(makeOperator("diagnose","CLASSIFY_CAUSAL_DIAGNOSTICS",{"baseline_classified"},{"baseline"},{"diagnostics_classified"},{"diagnostics_reference_contract"}));baseline.status=StrategyStatus::Executable;baseline.confidence=0.75;result.push_back(baseline);
    bool link=false,abi=false,configuration=false,test=false;for(const auto& diagnostic:request.diagnostics){link|=diagnostic.classification==BuildDiagnosticClass::MissingLinkLibrary||diagnostic.classification==BuildDiagnosticClass::WrongTargetDependency;abi|=diagnostic.classification==BuildDiagnosticClass::AbiIncompatibility;configuration|=diagnostic.classification==BuildDiagnosticClass::CMakeConfiguration||diagnostic.classification==BuildDiagnosticClass::MissingConfiguredInclude;test|=diagnostic.classification==BuildDiagnosticClass::TestFailure;}
    if((link||abi||configuration||test)&&result.size()<request.searchBudget){DevelopmentStrategy repair=baseline;repair.id="induced:causal-composition:"+std::to_string(stableHash(request.goal+join(repair.triggers,',')));repair.origin="new contrastive composition of known operators";repair.triggers.clear();for(const auto& diagnostic:request.diagnostics)repair.triggers.push_back(diagnosticName(diagnostic.classification));repair.operators.erase(repair.operators.begin()+1,repair.operators.end());std::string previous="discover";if(configuration){repair.operators.push_back(makeOperator("contract-correction","CORRECT_BUILD_CONTRACT",{"contract_discovered"},{previous},{"configuration_consistent"},{"reconfigure_succeeds"}));previous="contract-correction";}if(link){repair.operators.push_back(makeOperator("target-graph","UPDATE_TARGET_GRAPH",{"contract_discovered","verified_transformation_evidence"},{previous},{"link_dependency_resolved"},{"link_succeeds"},true));previous="target-graph";}if(abi){repair.operators.push_back(makeOperator("abi","ADAPT_ABI_CONTRACT",{"symbol_and_type_evidence","verified_transformation_evidence"},{previous},{"abi_compatible"},{"boundary_tests_pass"},true));previous="abi";}repair.operators.push_back(makeOperator("rebuild","NATIVE_REBUILD",{"isolated_workspace"},{previous},{"artifacts_built"},{"native_exit_code_zero"}));repair.operators.push_back(makeOperator("verify","NATIVE_TEST",{"artifacts_built"},{"rebuild"},{"goal_verified"},{"tests_pass"}));repair.confidence=0.55;result.push_back(std::move(repair));}
    return result;
}

StrategyPlan AutonomousStrategyPlanner::plan(const StrategyPlanningRequest& request) const {StrategyPlan result;std::set<std::string> identities;for(const auto& strategy:request.experience)if(identities.insert(strategy.id).second&&strategyTransferScore(strategy,request.contract,request.diagnostics)>=0.65)result.candidates.push_back(strategy);DevelopmentStrategyInductionEngine engine;for(auto strategy:engine.induce(request))if(identities.insert(strategy.id).second)result.candidates.push_back(std::move(strategy));if(result.candidates.size()>request.searchBudget)result.candidates.resize(request.searchBudget);double best=-1.0;for(const auto& strategy:result.candidates){const auto score=strategyTransferScore(strategy,request.contract,request.diagnostics);if(score>best){best=score;result.selected=strategy;}}result.executable=best>=0.0&&!result.selected.operators.empty()&&acyclic(result.selected);result.rationale=result.executable?"Selected an acyclic executable operator graph compatible with the native build contract":"No strategy satisfied build-contract, graph and safety preconditions";return result;}

std::vector<DevelopmentStrategy> DevelopmentStrategyStore::load() const {std::vector<DevelopmentStrategy> result;if(path_.empty()||!std::filesystem::exists(path_))return result;std::ifstream input(path_,std::ios::binary);if(!input)throw std::runtime_error("Cannot open GDIS1 strategy store");std::string line;std::uint64_t expectedPrevious=0;while(std::getline(input,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty())continue;if(line!="GDIS1")throw std::runtime_error("Unsupported GDIS1 version");std::ostringstream body;body<<"GDIS1\n";DevelopmentStrategy strategy;bool haveStrategy=false,haveHash=false;while(std::getline(input,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();const auto fields=split(line,'|');if(fields[0]=="HASH"){if(fields.size()!=3||number(fields[1])!=expectedPrevious||number(fields[2])!=stableHash(body.str()))throw std::runtime_error("GDIS1 integrity chain mismatch");expectedPrevious=number(fields[2]);haveHash=true;break;}body<<line<<'\n';if(fields[0]=="STRATEGY"&&fields.size()==9){strategy.id=unhex(fields[1]);strategy.version=unhex(fields[2]);strategy.goal=unhex(fields[3]);strategy.origin=unhex(fields[4]);strategy.requiredBuildSystem=unhex(fields[5]);strategy.requiredCompilerFamily=unhex(fields[6]);strategy.confidence=std::stod(fields[7]);const auto status=number(fields[8]);if(status>static_cast<unsigned>(StrategyStatus::Uncertain))throw std::runtime_error("Invalid GDIS1 status");strategy.status=static_cast<StrategyStatus>(status);haveStrategy=true;}else if(fields[0]=="LIST"&&fields.size()==3)appendList(strategy,fields[1],unhex(fields[2]));else if(fields[0]=="OP"&&fields.size()==8)strategy.operators.push_back({unhex(fields[1]),unhex(fields[2]),decodedList(fields[3]),decodedList(fields[4]),decodedList(fields[5]),decodedList(fields[6]),number(fields[7])!=0});else throw std::runtime_error("Corrupt GDIS1 record");}if(!haveStrategy||!haveHash||strategy.id.empty()||strategy.version!="1"||!acyclic(strategy))throw std::runtime_error("Invalid GDIS1 strategy");result.push_back(std::move(strategy));}return result;}

void DevelopmentStrategyStore::append(const DevelopmentStrategy& strategy) const {if(path_.empty())return;if(strategy.id.empty()||strategy.version!="1"||!acyclic(strategy))throw std::invalid_argument("Cannot persist invalid development strategy");const auto existing=load();if(std::any_of(existing.begin(),existing.end(),[&](const auto& item){return item.id==strategy.id&&item.version==strategy.version;}))return;std::uint64_t previous=0;if(!existing.empty()){std::ifstream input(path_,std::ios::binary);std::string line;while(std::getline(input,line))if(line.starts_with("HASH|")){const auto fields=split(line,'|');if(fields.size()==3)previous=number(fields[2]);}}const auto body="GDIS1\n"+serializeStrategy(strategy);if(!path_.parent_path().empty())std::filesystem::create_directories(path_.parent_path());std::ofstream output(path_,std::ios::binary|std::ios::app);output<<body<<"HASH|"<<previous<<'|'<<stableHash(body)<<'\n';if(!output)throw std::runtime_error("Cannot append GDIS1 strategy store");}
void DevelopmentStrategyStore::replace(const std::vector<DevelopmentStrategy>& strategies) const {if(path_.empty())return;const auto temporary=path_.string()+".tmp";std::error_code error;std::filesystem::remove(temporary,error);DevelopmentStrategyStore store(temporary);for(const auto& strategy:strategies)store.append(strategy);std::filesystem::rename(temporary,path_,error);if(error){std::filesystem::remove(path_,error);error.clear();std::filesystem::rename(temporary,path_,error);}if(error)throw std::runtime_error("Cannot atomically replace GDIS1 strategy store");}

StrategyExecutionResult executeDevelopmentStrategy(const DevelopmentStrategy& strategy,const BuildContract& contract,const NativeBuildConfig& config){StrategyExecutionResult result;result.strategy=strategy;if(!compatible(strategy,contract)){result.terminationReason="strategy_rejected_by_build_contract";return result;}if(!acyclic(strategy)){result.terminationReason="invalid_or_cyclic_operator_graph";return result;}std::set<std::string> completed;bool nativeExecuted=false;std::filesystem::create_directories(config.isolatedWorkspace.parent_path());result.snapshotPath=config.isolatedWorkspace.parent_path()/(config.isolatedWorkspace.filename().string()+".strategy.snapshot.gdibc");saveBuildContract(contract,result.snapshotPath);for(std::size_t index=0;index<strategy.operators.size();++index){const auto& operation=strategy.operators[index];StrategyExecutionStep step;step.operatorId=operation.id;step.inputState=completed.empty()?"initial":"progress";step.prerequisitesMet=std::all_of(operation.dependsOn.begin(),operation.dependsOn.end(),[&](const auto& dependency){return completed.contains(dependency);});if(!step.prerequisitesMet){step.reason="operator dependency not satisfied";result.steps.push_back(std::move(step));result.terminationReason="invalid_operator_graph";result.nextOperator=index;return result;}if(operation.mutatesSources){step.reason="source mutation blocked: verified transformation evidence is not attached to the operator";step.outputState="rolled_back";result.steps.push_back(std::move(step));result.terminationReason="unauthorized_source_mutation_blocked";result.rolledBack=true;result.nextOperator=index;return result;}if((operation.operation=="RECONSTRUCT_BASELINE"||operation.operation=="NATIVE_REBUILD"||operation.operation=="NATIVE_TEST")&&!nativeExecuted){result.build=executeNativeBuild(contract,config);nativeExecuted=true;step.succeeded=result.build.baselineStatus!=BuildBaselineStatus::BuildContractUnverified&&result.build.baselineStatus!=BuildBaselineStatus::BaselineInconclusive;step.diagnostics=result.build.diagnostics;step.reason=toString(result.build.baselineStatus);}else{step.succeeded=true;step.reason="operator completed from verified contract/evidence state";}step.outputState=step.succeeded?"completed":"failed";result.steps.push_back(step);result.nextOperator=index+1;if(!step.succeeded){result.terminationReason="operator_failed:"+operation.id;return result;}completed.insert(operation.id);}result.success=nativeExecuted&&result.build.baselineStatus==BuildBaselineStatus::BaselineReproduced;result.terminationReason=result.success?"strategy_verified":"baseline_classified_no_repair_authorized";result.strategy.status=result.success?StrategyStatus::Succeeded:StrategyStatus::Uncertain;result.reportPath=config.isolatedWorkspace.parent_path()/(config.isolatedWorkspace.filename().string()+".strategy.json");std::ofstream report(result.reportPath);report<<"{\n  \"format\": \"GDI-strategy-execution-v2\",\n  \"strategy\": \""<<result.strategy.id<<"\",\n  \"success\": "<<(result.success?"true":"false")<<",\n  \"rolled_back\": "<<(result.rolledBack?"true":"false")<<",\n  \"next_operator\": "<<result.nextOperator<<",\n  \"termination\": \""<<result.terminationReason<<"\",\n  \"steps\": "<<result.steps.size()<<"\n}\n";return result;}
} // namespace genomic::gpi
